#include "arm64_emulate_internal.h"

/* ======================== FP / AdvSIMD：固定硬件模板与现场转换辅助 ======================== */

// clang-format off
static inline bool emu_fp_unary_merge_hw(enum arm64_instruction instruction, void *dst, const void *source, uint32_t element_width)
{
    switch (instruction)
    {
    case ARM64_INSN_FCVT_D_S:
        emu_template_fp_fcvt_d_s_merge(dst, source);
        return true;
    case ARM64_INSN_FCVT_S_D:
        emu_template_fp_fcvt_s_d_merge(dst, source);
        return true;
    case ARM64_INSN_XTN2_VECTOR:
        switch (element_width)
        {
        case 16: emu_template_simd_xtn2_16b_8h_merge(dst, source); break;
        case 32: emu_template_simd_xtn2_8h_4s_merge(dst, source); break;
        case 64: emu_template_simd_xtn2_4s_2d_merge(dst, source); break;
        default: return false;
        }
        return true;
    case ARM64_INSN_SQXTN2_VECTOR:
        switch (element_width)
        {
        case 16: emu_template_simd_sqxtn2_16b_8h_merge(dst, source); break;
        case 32: emu_template_simd_sqxtn2_8h_4s_merge(dst, source); break;
        case 64: emu_template_simd_sqxtn2_4s_2d_merge(dst, source); break;
        default: return false;
        }
        return true;
    case ARM64_INSN_SQXTUN2_VECTOR:
        switch (element_width)
        {
        case 16: emu_template_simd_sqxtun2_16b_8h_merge(dst, source); break;
        case 32: emu_template_simd_sqxtun2_8h_4s_merge(dst, source); break;
        case 64: emu_template_simd_sqxtun2_4s_2d_merge(dst, source); break;
        default: return false;
        }
        return true;
    case ARM64_INSN_UQXTN2_VECTOR:
        switch (element_width)
        {
        case 16: emu_template_simd_uqxtn2_16b_8h_merge(dst, source); break;
        case 32: emu_template_simd_uqxtn2_8h_4s_merge(dst, source); break;
        case 64: emu_template_simd_uqxtn2_4s_2d_merge(dst, source); break;
        default: return false;
        }
        return true;
    default:
        return false;
    }
}

static inline bool emu_gpr_to_fp_hw(enum arm64_instruction instruction, void *dst, uint64_t value)
{
    switch (instruction)
    {
    case ARM64_INSN_SCVTF_S_W: emu_template_fp_scvtf_s_w_merge(dst, value); return true;
    case ARM64_INSN_UCVTF_S_W: emu_template_fp_ucvtf_s_w_merge(dst, value); return true;
    case ARM64_INSN_SCVTF_D_W: emu_template_fp_scvtf_d_w_merge(dst, value); return true;
    case ARM64_INSN_UCVTF_D_W: emu_template_fp_ucvtf_d_w_merge(dst, value); return true;
    case ARM64_INSN_SCVTF_S_X: emu_template_fp_scvtf_s_x_merge(dst, value); return true;
    case ARM64_INSN_UCVTF_S_X: emu_template_fp_ucvtf_s_x_merge(dst, value); return true;
    case ARM64_INSN_SCVTF_D_X: emu_template_fp_scvtf_d_x_merge(dst, value); return true;
    case ARM64_INSN_UCVTF_D_X: emu_template_fp_ucvtf_d_x_merge(dst, value); return true;
    default: return false;
    }
}
// clang-format on

