static inline bool emu_simd_rdm_accumulate_hw(enum arm64_instruction instruction, void *dst, const void *left, const void *right, uint32_t operand_width, uint32_t element_width)
{
    switch (instruction)
    {
    case ARM64_INSN_SQRDMLAH_VECTOR:
    case ARM64_INSN_SQRDMLAH_VECTOR_BY_ELEMENT:
        switch (operand_width)
        {
        case 64:
            switch (element_width)
            {
            case 16: emu_template_simd_sqrdmlah_4h_accumulate(dst, left, right); break;
            case 32: emu_template_simd_sqrdmlah_2s_accumulate(dst, left, right); break;
            default: return false;
            }
            break;
        case 128:
            switch (element_width)
            {
            case 16: emu_template_simd_sqrdmlah_8h_accumulate(dst, left, right); break;
            case 32: emu_template_simd_sqrdmlah_4s_accumulate(dst, left, right); break;
            default: return false;
            }
            break;
        default: return false;
        }
        return true;
    case ARM64_INSN_SQRDMLSH_VECTOR:
    case ARM64_INSN_SQRDMLSH_VECTOR_BY_ELEMENT:
        switch (operand_width)
        {
        case 64:
            switch (element_width)
            {
            case 16: emu_template_simd_sqrdmlsh_4h_accumulate(dst, left, right); break;
            case 32: emu_template_simd_sqrdmlsh_2s_accumulate(dst, left, right); break;
            default: return false;
            }
            break;
        case 128:
            switch (element_width)
            {
            case 16: emu_template_simd_sqrdmlsh_8h_accumulate(dst, left, right); break;
            case 32: emu_template_simd_sqrdmlsh_4s_accumulate(dst, left, right); break;
            default: return false;
            }
            break;
        default: return false;
        }
        return true;
    case ARM64_INSN_SQRDMLAH_SCALAR:
    case ARM64_INSN_SQRDMLAH_SCALAR_BY_ELEMENT:
        switch (element_width)
        {
        case 16: emu_template_simd_sqrdmlah_h_scalar_accumulate(dst, left, right); break;
        case 32: emu_template_simd_sqrdmlah_s_scalar_accumulate(dst, left, right); break;
        default: return false;
        }
        return true;
    case ARM64_INSN_SQRDMLSH_SCALAR:
    case ARM64_INSN_SQRDMLSH_SCALAR_BY_ELEMENT:
        switch (element_width)
        {
        case 16: emu_template_simd_sqrdmlsh_h_scalar_accumulate(dst, left, right); break;
        case 32: emu_template_simd_sqrdmlsh_s_scalar_accumulate(dst, left, right); break;
        default: return false;
        }
        return true;
    default:
        return false;
    }
}

