/* ======================== FP / AdvSIMD：缓存条目执行模板 ======================== */

static inline enum emu_insn_result emu_finish_simd(struct pt_regs *regs, bool handled)
{
    if (!handled) return EMU_INSN_SKIP;
    regs->pc += 4;
    return EMU_INSN_HANDLED;
}

/* 每个固定 FP / AdvSIMD 执行模板直接对应缓存条目中的 execute 函数地址。 */

static enum emu_insn_result emu_execute_simd_uzp1_vector_w64_ew8(struct pt_regs *regs, struct fp_regs *fp_regs, const struct arm64_executor_entry *entry)
{
    return emu_finish_simd(regs, emu_simd_permute_vector_hw(ARM64_INSN_UZP1_VECTOR, &fp_regs->q[entry->reg0], &fp_regs->q[entry->reg1], &fp_regs->q[entry->reg2], 64, 8));
}

