static enum emu_insn_result emu_execute_simd_fccmp_scalar_w8_cond0(struct pt_regs *regs, struct fp_regs *fp_regs, const struct arm64_executor_entry *entry)
{
    uint64_t nzcv;

    if (8 == 16 && !arm64_current_cpu_has_fp16()) return emu_finish_simd(regs, false);
    if (!emu_cond_holds(emu_read_nzcv(regs), 0))
    {
        emu_write_nzcv(regs, (uint64_t)entry->operand0 << 28);
        return emu_finish_simd(regs, true);
    }
    if (!emu_scalar_fp_compare_register_hw(8, &fp_regs->q[entry->reg1], &fp_regs->q[entry->reg2], &nzcv)) return emu_finish_simd(regs, false);
    emu_write_nzcv(regs, nzcv);
    return emu_finish_simd(regs, true);
}

