/* 2348 shape-specialized executor leaves. */

/* ======================== FP / AdvSIMD：解码结果构建缓存条目 ======================== */

bool emu_build_simd_executor(const struct arm64_decoded_instruction *decoded, struct arm64_executor_entry *entry)
{
    entry->execute = emu_select_simd_executor(decoded);
    if (!entry->execute) return false;


    entry->operand0 = decoded->immediate;
    entry->operand1 = decoded->expanded_immediate;
    entry->reg0 = decoded->rd;
    entry->reg1 = decoded->rn;
    entry->reg2 = decoded->rm;
    entry->reg3 = decoded->ra;
    entry->reg4 = decoded->operand_width;
    entry->reg5 = decoded->element_width;
    entry->option0 = decoded->lane_index;
    entry->option1 = decoded->source_lane_index | decoded->condition;
    return true;
}

